/****************************************************************************
* Mes plugin table rowspan 1.0.0
*
* Date : 2014-10-18
*
* Author ：Alen Liu
*
*
* Desc: 合并行插件，使用$("#tableID").rowspan(用来判断合并的列,要合并到第几列)，如：根据第一列，合并前5列，$("#tableID").rowspan(0,5)
*
* Copyright(c) 2014 All Rights Reserved.   [ shzalen@163.com ].
*
****************************************************************************/

jQuery.fn.rowspan = function (b, a) { return this.each(function () { var c; $("tr", this).each(function (d) { $("td:eq(" + b + ")", this).filter(":visible").each(function (e) { if (c != null && $(this).html() == $(c).html()) { rowspan = $(c).attr("rowSpan"); if (rowspan == undefined) { $(c).attr("rowSpan", 1); if (a > 0) { $(c).parent().children("td:lt(" + a + ")").attr("rowSpan", 1) } rowspan = $(c).attr("rowSpan") } rowspan = Number(rowspan) + 1; $(c).attr("rowSpan", rowspan); if (a > 0) { $(c).parent().children("td:lt(" + a + ")").attr("rowSpan", rowspan); $(this).parent().children("td:lt(" + a + ")").hide() } $(this).hide() } else { c = this } }) }) }) };
